window.HCW_SEARCH=[{"kind":"Lesson 01.01","title":"What a computer actually is","summary":"Why can a machine follow instructions? A computer is a collection of parts that change and store physical states according to rules.","url":"../chapters/what-a-computer-actually-is.html"},{"kind":"Lesson 01.02","title":"Voltage is not literally a one","summary":"How does electricity become a bit? A wire carries a changing voltage, and a receiving circuit interprets a voltage range as low or high.","url":"../chapters/voltage-is-not-literally-a-one.html"},{"kind":"Lesson 01.03","title":"Noise and reliable decisions","summary":"Why only two states? Real signals fluctuate; separating two valid regions leaves room for imperfections.","url":"../chapters/noise-and-reliable-decisions.html"},{"kind":"Lesson 01.04","title":"Transistors as controlled switches","summary":"What makes a circuit controllable? A transistor can use one electrical signal to regulate another, enabling enormous networks of on/off behavior.","url":"../chapters/transistors-as-controlled-switches.html"},{"kind":"Lesson 01.05","title":"Bits, bytes, and meaning","summary":"When does a bit become information? A bit distinguishes two states; a convention assigns meaning to patterns of bits.","url":"../chapters/bits-bytes-and-meaning.html"},{"kind":"Lesson 01.06","title":"The abstraction ladder","summary":"How can trillions of tiny events seem simple? Engineers build layers: physical devices, gates, circuits, processor, instructions, software, applications.","url":"../chapters/the-abstraction-ladder.html"},{"kind":"Lesson 02.01","title":"Decimal is already a code","summary":"Why is 724 equal to 724? Each decimal digit has a positional weight: ones, tens, hundreds and so on.","url":"../chapters/decimal-is-already-a-code.html"},{"kind":"Lesson 02.02","title":"Binary positional weights","summary":"What changes when the base is two? The positions weigh 1, 2, 4, 8, 16, 32 and continue doubling.","url":"../chapters/binary-positional-weights.html"},{"kind":"Lesson 02.03","title":"Binary to decimal","summary":"How do you read an unfamiliar bit pattern? Multiply every bit by its power-of-two weight, then sum only the active weights.","url":"../chapters/binary-to-decimal.html"},{"kind":"Lesson 02.04","title":"Decimal to binary","summary":"How do you write 45 with only 0 and 1? Repeatedly subtract the largest fitting power of two, or repeatedly divide by two and collect remainders.","url":"../chapters/decimal-to-binary.html"},{"kind":"Lesson 02.05","title":"Fixed-width numbers","summary":"Why does bit width matter? With n independent bits there are 2ⁿ patterns; their interpretation determines what range they represent.","url":"../chapters/fixed-width-numbers.html"},{"kind":"Lesson 02.06","title":"Hexadecimal as shorthand","summary":"Why do engineers use A–F? Hexadecimal groups four binary digits into one symbol from 0–9 or A–F.","url":"../chapters/hexadecimal-as-shorthand.html"},{"kind":"Lesson 03.01","title":"Binary counting and carrying","summary":"How can 1+1 produce 10? A binary digit holds only zero or one; exceeding one produces a carry to the next column.","url":"../chapters/binary-counting-and-carrying.html"},{"kind":"Lesson 03.02","title":"Adding several bits","summary":"What if two operands and a carry meet? The sum of three single bits can be 0, 1, 2 or 3; output is the low bit and carry is the high bit.","url":"../chapters/adding-several-bits.html"},{"kind":"Lesson 03.03","title":"Two’s complement","summary":"How can a bit pattern mean negative five? In n-bit two’s complement, the leading position has weight −2ⁿ⁻¹ and the other positions remain positive.","url":"../chapters/two-s-complement.html"},{"kind":"Lesson 03.04","title":"Negating with invert-plus-one","summary":"Why flip bits and add one? For fixed-width n-bit arithmetic, the bitwise complement plus one equals the additive inverse modulo 2ⁿ.","url":"../chapters/negating-with-invert-plus-one.html"},{"kind":"Lesson 03.05","title":"Subtraction is addition","summary":"Why does one adder do both jobs? A − B is computed as A + (NOT B) + 1 using the same fixed-width binary adder.","url":"../chapters/subtraction-is-addition.html"},{"kind":"Lesson 03.06","title":"Overflow and status flags","summary":"When can correct circuitry produce the wrong answer? A finite register wraps modulo 2ⁿ; signed overflow occurs when a mathematical result exceeds its signed range.","url":"../chapters/overflow-and-status-flags.html"},{"kind":"Lesson 04.01","title":"Truth tables","summary":"Can a complete behavior fit in four rows? A truth table lists every input combination and the corresponding output.","url":"../chapters/truth-tables.html"},{"kind":"Lesson 04.02","title":"AND and OR","summary":"When must conditions agree? AND produces one only when every input is one; OR produces one when at least one input is one.","url":"../chapters/and-and-or.html"},{"kind":"Lesson 04.03","title":"NOT, NAND, NOR","summary":"Why is inversion so powerful? NOT reverses a bit; NAND and NOR invert AND and OR results.","url":"../chapters/not-nand-nor.html"},{"kind":"Lesson 04.04","title":"XOR and equality","summary":"Which gate detects differences? XOR outputs one when its inputs differ; XNOR outputs one when they match.","url":"../chapters/xor-and-equality.html"},{"kind":"Lesson 04.05","title":"Multiplexers and selectors","summary":"How does a computer choose one value? A 2-to-1 multiplexer outputs A when select is zero and B when select is one.","url":"../chapters/multiplexers-and-selectors.html"},{"kind":"Lesson 04.06","title":"Decoders and enable lines","summary":"How can two address bits pick one of four places? A decoder asserts a distinct output for each input code, often conditioned on enable.","url":"../chapters/decoders-and-enable-lines.html"},{"kind":"Lesson 05.01","title":"The half adder","summary":"Can two gates add two bits? A half adder uses XOR for sum and AND for carry-out.","url":"../chapters/the-half-adder.html"},{"kind":"Lesson 05.02","title":"The full adder","summary":"What was the missing input? A full adder combines A, B and carry-in, producing sum and carry-out.","url":"../chapters/the-full-adder.html"},{"kind":"Lesson 05.03","title":"Ripple carry addition","summary":"How do eight bits cooperate? Connect each stage’s carry-out to the next stage’s carry-in.","url":"../chapters/ripple-carry-addition.html"},{"kind":"Lesson 05.04","title":"Subtraction with XOR controls","summary":"How can the same gates subtract? Route each B bit through XOR with a SUB control and make that control the first carry-in.","url":"../chapters/subtraction-with-xor-controls.html"},{"kind":"Lesson 05.05","title":"The arithmetic logic unit","summary":"How does a processor choose ADD or AND? An ALU computes arithmetic and bitwise results and selects an output using operation control bits.","url":"../chapters/the-arithmetic-logic-unit.html"},{"kind":"Lesson 05.06","title":"Flags from arithmetic","summary":"How can later instructions know what happened? Extra circuit outputs can report zero, negative, carry and signed overflow status.","url":"../chapters/flags-from-arithmetic.html"},{"kind":"Lesson 06.01","title":"Combinational vs sequential","summary":"What changes when a circuit remembers? Combinational output depends on current inputs; sequential output also depends on stored state.","url":"../chapters/combinational-vs-sequential.html"},{"kind":"Lesson 06.02","title":"Feedback creates a latch","summary":"Can logic gates sustain a state? Cross-coupled gates feed back into one another, allowing two stable logic conditions.","url":"../chapters/feedback-creates-a-latch.html"},{"kind":"Lesson 06.03","title":"The gated D latch","summary":"How do we avoid ambiguous set/reset controls? A D latch presents one data input and an enable that decides whether data is copied or retained.","url":"../chapters/the-gated-d-latch.html"},{"kind":"Lesson 06.04","title":"Edge-triggered flip-flops","summary":"How does a clock create orderly updates? An edge-triggered D flip-flop captures input at a chosen clock transition and holds the result.","url":"../chapters/edge-triggered-flip-flops.html"},{"kind":"Lesson 06.05","title":"Registers from flip-flops","summary":"How can a circuit remember a whole number? Place several flip-flops side by side under a shared clock and load-enable control.","url":"../chapters/registers-from-flip-flops.html"},{"kind":"Lesson 06.06","title":"Counters and the clock","summary":"How does hardware keep track of a step number? Feed a register output through an incrementer and load the incremented value on each clock edge.","url":"../chapters/counters-and-the-clock.html"},{"kind":"Lesson 07.01","title":"Why a computer needs storage","summary":"What happens after the ALU finishes? A computed result must be retained somewhere so a later operation can reuse it.","url":"../chapters/why-a-computer-needs-storage.html"},{"kind":"Lesson 07.02","title":"Addressing memory","summary":"How do you choose a storage location? An address selects a memory location; a data value is the bit pattern stored there.","url":"../chapters/addressing-memory.html"},{"kind":"Lesson 07.03","title":"Reading and writing RAM","summary":"How are stored bytes changed? A write selects a location and supplies new data; a read selects a location and receives existing data.","url":"../chapters/reading-and-writing-ram.html"},{"kind":"Lesson 07.04","title":"Building small memory","summary":"Can gates build a memory array? Use storage cells, row selection and output selection logic to construct a simple register-file-like memory.","url":"../chapters/building-small-memory.html"},{"kind":"Lesson 07.05","title":"ROM and lookup tables","summary":"Can a circuit output stored patterns without writes? ROM holds predefined data or control patterns, indexed by address.","url":"../chapters/rom-and-lookup-tables.html"},{"kind":"Lesson 07.06","title":"The shared bus","summary":"How can several parts exchange one word? A bus is a coordinated group of signal lines, often with selection, direction and control rules.","url":"../chapters/the-shared-bus.html"},{"kind":"Lesson 08.01","title":"The accumulator model","summary":"Where does a CPU keep the current answer? A simple accumulator CPU uses one main register as a frequent ALU source and destination.","url":"../chapters/the-accumulator-model.html"},{"kind":"Lesson 08.02","title":"General-purpose registers","summary":"Why keep several values close to the ALU? Registers provide fast, small storage directly managed by instructions.","url":"../chapters/general-purpose-registers.html"},{"kind":"Lesson 08.03","title":"The instruction register","summary":"How does a CPU hold its current command? An instruction register captures the instruction bits being decoded and executed.","url":"../chapters/the-instruction-register.html"},{"kind":"Lesson 08.04","title":"The program counter","summary":"How does a computer know the next instruction? PC stores the address of the next instruction to fetch, subject to branching.","url":"../chapters/the-program-counter.html"},{"kind":"Lesson 08.05","title":"Fetch, decode, execute","summary":"What repeats while code runs? Fetch gets instruction bits, decode chooses a behavior, execute changes registers, memory or PC.","url":"../chapters/fetch-decode-execute.html"},{"kind":"Lesson 08.06","title":"Datapath versus control","summary":"Who moves the data and who decides when? The datapath performs operations and carries values; control drives selectors, loads and enables.","url":"../chapters/datapath-versus-control.html"},{"kind":"Lesson 09.01","title":"Instruction encoding","summary":"How can a byte command a processor? Reserve some instruction bits for opcode and others for register IDs or immediate values.","url":"../chapters/instruction-encoding.html"},{"kind":"Lesson 09.02","title":"Instruction set architecture","summary":"What is a contract between code and hardware? An ISA specifies programmer-visible instructions, registers, behavior and relevant memory rules.","url":"../chapters/instruction-set-architecture.html"},{"kind":"Lesson 09.03","title":"Control signals","summary":"How does a decoded opcode operate wires? Control logic turns instruction fields and timing state into load, enable, select and write signals.","url":"../chapters/control-signals.html"},{"kind":"Lesson 09.04","title":"Microcode ROM","summary":"Can a table orchestrate the CPU? A control ROM maps an instruction and microstep to a word of control bits.","url":"../chapters/microcode-rom.html"},{"kind":"Lesson 09.05","title":"Clock timing and hazards","summary":"Why does operation order matter? Propagation, setup/hold, and shared resource conflicts determine when values can safely be captured.","url":"../chapters/clock-timing-and-hazards.html"},{"kind":"Lesson 09.06","title":"Conditional branches and flags","summary":"How does code make an if-statement? A branch instruction tests status information and selects either sequential or target PC.","url":"../chapters/conditional-branches-and-flags.html"},{"kind":"Lesson 10.01","title":"Assembly from ideas","summary":"How do human-readable instructions become bytes? Assembly uses readable mnemonics that an assembler encodes into machine instructions.","url":"../chapters/assembly-from-ideas.html"},{"kind":"Lesson 10.02","title":"The first program","summary":"Can a few instructions produce a visible result? A program is an ordered collection of operations that move and transform state.","url":"../chapters/the-first-program.html"},{"kind":"Lesson 10.03","title":"Loops and stopping","summary":"Why does one instruction run many times? A branch can move PC to an earlier address; a condition decides when to stop repeating.","url":"../chapters/loops-and-stopping.html"},{"kind":"Lesson 10.04","title":"Fibonacci by repeated addition","summary":"How does a simple CPU calculate a sequence? Keep two consecutive values; output one and replace the pair with old-second and their sum.","url":"../chapters/fibonacci-by-repeated-addition.html"},{"kind":"Lesson 10.05","title":"Reading a timing trace","summary":"How do you debug a program without guessing? Record register, bus, PC, control state and memory values after important steps.","url":"../chapters/reading-a-timing-trace.html"},{"kind":"Lesson 10.06","title":"The software/hardware boundary","summary":"What part is programmable? Instructions express allowed behaviors; underlying hardware implements those behaviors.","url":"../chapters/the-software-hardware-boundary.html"},{"kind":"Lesson 11.01","title":"First-generation phone silicon","summary":"Was a real smartphone fundamentally different? The original 2007 iPhone used a Samsung S5L8900 system-on-chip with an ARM11-class ARM1176JZF-S core.","url":"../chapters/first-generation-phone-silicon.html"},{"kind":"Lesson 11.02","title":"ARMv6 registers and execution","summary":"What makes assembly on ARM more expressive? ARM-style instructions can name multiple registers, perform operations and access memory with explicit conventions.","url":"../chapters/armv6-registers-and-execution.html"},{"kind":"Lesson 11.03","title":"Load/store architecture","summary":"Why are RAM operations distinct? In a typical ARM load/store design, arithmetic operates on registers while dedicated load/store instructions access memory.","url":"../chapters/load-store-architecture.html"},{"kind":"Lesson 11.04","title":"Hex and actual instruction bytes","summary":"Why do machine-code tools display 0x? Engineers view binary in hexadecimal because each hex digit corresponds exactly to four bits.","url":"../chapters/hex-and-actual-instruction-bytes.html"},{"kind":"Lesson 11.05","title":"Memory-mapped I/O","summary":"How can code control an LED? A processor can control peripheral registers by reading and writing addresses mapped to hardware rather than ordinary RAM.","url":"../chapters/memory-mapped-i-o.html"},{"kind":"Lesson 11.06","title":"Real-time and device limits","summary":"Why are real microcontrollers more demanding? Physical devices have voltage, current, timing, safety and ownership constraints outside pure code.","url":"../chapters/real-time-and-device-limits.html"},{"kind":"Lesson 12.01","title":"The operating system","summary":"Why can many programs share one machine? An operating system coordinates process execution, memory, files, devices, permissions and system calls.","url":"../chapters/the-operating-system.html"},{"kind":"Lesson 12.02","title":"Interrupts and exceptions","summary":"What if something urgent happens? Interrupts and exceptions redirect execution to special handlers while preserving a return path.","url":"../chapters/interrupts-and-exceptions.html"},{"kind":"Lesson 12.03","title":"Cache and the memory hierarchy","summary":"Why is a CPU faster than RAM? Fast small storage reduces average access time by keeping likely-needed instructions and data nearby.","url":"../chapters/cache-and-the-memory-hierarchy.html"},{"kind":"Lesson 12.04","title":"Pipelining and parallel work","summary":"Can a CPU overlap instructions? A pipeline divides instruction handling into stages so different instructions occupy different stages concurrently.","url":"../chapters/pipelining-and-parallel-work.html"},{"kind":"Lesson 12.05","title":"Compilers and high-level languages","summary":"How does familiar code turn into machine actions? Compilers transform higher-level program meaning into lower-level operations and instruction sequences.","url":"../chapters/compilers-and-high-level-languages.html"},{"kind":"Lesson 12.06","title":"Everything is layers","summary":"How do you keep a complete mental model? A computing system is a stack of representations and contracts, from voltages through bits and gates to software.","url":"../chapters/everything-is-layers.html"},{"kind":"Part 01","title":"From electricity to information","summary":"Begin with the physical signal, and discover why a simple yes/no distinction changes everything.","url":"../parts/01.html"},{"kind":"Part 02","title":"Numbers made from bits","summary":"Learn to see patterns such as 101101 as structured values rather than mysterious strings.","url":"../parts/02.html"},{"kind":"Part 03","title":"Arithmetic, signs, and overflow","summary":"Build the mathematics that later becomes a physical arithmetic circuit.","url":"../parts/03.html"},{"kind":"Part 04","title":"Logic gates and decisions","summary":"Turn Boolean rules into circuits that can genuinely select and calculate.","url":"../parts/04.html"},{"kind":"Part 05","title":"From gates to an ALU","summary":"Make an actual computing block, then extend it to do several operations.","url":"../parts/05.html"},{"kind":"Part 06","title":"Memory of a single bit","summary":"Cross the gap between circuits that react now and circuits that remember later.","url":"../parts/06.html"},{"kind":"Part 07","title":"RAM, ROM, and moving data","summary":"Understand where bits wait, how they are addressed, and how they move.","url":"../parts/07.html"},{"kind":"Part 08","title":"Assembling a CPU datapath","summary":"Join the calculator, memory, counters, and communication lines into one machine.","url":"../parts/08.html"},{"kind":"Part 09","title":"Instructions and control","summary":"Define a tiny processor language and make every instruction physically executable.","url":"../parts/09.html"},{"kind":"Part 10","title":"Programs on a tiny CPU","summary":"Write and trace full programs so the components become a real computing system.","url":"../parts/10.html"},{"kind":"Part 11","title":"From toy CPU to real ARM","summary":"Connect educational building blocks to an actual processor family and external hardware.","url":"../parts/11.html"},{"kind":"Part 12","title":"The wider computer system","summary":"Understand what was deliberately simplified and how a modern computer grows from the same ideas.","url":"../parts/12.html"},{"kind":"Live lab","title":"Binary workbench","summary":"Turn individual bits on and off; the decimal and hex readings update instantly.","url":"../labs/binary-workbench.html"},{"kind":"Live lab","title":"Number converter","summary":"Convert in either direction, then compare signed and unsigned interpretations.","url":"../labs/number-converter.html"},{"kind":"Live lab","title":"Logic gate explorer","summary":"Switch A and B, select a gate, and observe the output with its truth table.","url":"../labs/gate-explorer.html"},{"kind":"Live lab","title":"Full adder lab","summary":"Change A, B and carry-in to witness sum and carry-out.","url":"../labs/full-adder-lab.html"},{"kind":"Live lab","title":"Eight-bit ALU","summary":"Choose two eight-bit inputs and an operation; inspect the result and status flags.","url":"../labs/alu-playground.html"},{"kind":"Live lab","title":"Clock and register","summary":"Set an incoming byte and tick the clock to capture it into a register.","url":"../labs/clock-register.html"},{"kind":"Live lab","title":"Tiny RAM simulator","summary":"Read, write, and inspect all sixteen addressable bytes.","url":"../labs/ram-lab.html"},{"kind":"Live lab","title":"CPU instruction tracer","summary":"Step through an educational accumulator program and watch PC, ACC and flags.","url":"../labs/instruction-tracer.html"},{"kind":"Live lab","title":"Seven-segment display","summary":"Toggle segment lines or choose a decimal digit; see a hardware-style display.","url":"../labs/seven-segment.html"},{"kind":"Live lab","title":"Fibonacci machine","summary":"Advance register updates one step at a time and watch the sequence grow.","url":"../labs/fibonacci-machine.html"},{"kind":"Glossary","title":"Bit","summary":"One binary distinction: 0 or 1, represented physically by a distinguishable state.","url":"glossary.html#bit"},{"kind":"Glossary","title":"Byte","summary":"A group of eight bits; it has 256 possible patterns.","url":"glossary.html#byte"},{"kind":"Glossary","title":"Voltage","summary":"An electrical potential difference. Logic circuits interpret ranges of voltages as low or high.","url":"glossary.html#voltage"},{"kind":"Glossary","title":"Logic level","summary":"An interpreted state, usually LOW or HIGH, associated with a valid input range.","url":"glossary.html#logic-level"},{"kind":"Glossary","title":"Noise margin","summary":"The allowed difference between a valid output level and the threshold that a receiver must recognize.","url":"glossary.html#noise-margin"},{"kind":"Glossary","title":"Transistor","summary":"A semiconductor component that can control current; the central switching device in ordinary digital circuits.","url":"glossary.html#transistor"},{"kind":"Glossary","title":"CMOS","summary":"A common integrated-circuit technology that combines complementary types of MOS transistors.","url":"glossary.html#cmos"},{"kind":"Glossary","title":"Logic gate","summary":"A circuit implementing a Boolean operation on one or more digital inputs.","url":"glossary.html#logic-gate"},{"kind":"Glossary","title":"Truth table","summary":"A complete listing of input combinations and corresponding outputs for a logical function.","url":"glossary.html#truth-table"},{"kind":"Glossary","title":"Boolean algebra","summary":"Mathematics of true/false relationships, including AND, OR and NOT.","url":"glossary.html#boolean-algebra"},{"kind":"Glossary","title":"AND","summary":"A Boolean operation that returns one only when all inputs are one.","url":"glossary.html#and"},{"kind":"Glossary","title":"OR","summary":"A Boolean operation that returns one when at least one input is one.","url":"glossary.html#or"},{"kind":"Glossary","title":"NOT","summary":"A Boolean operation that inverts its single input.","url":"glossary.html#not"},{"kind":"Glossary","title":"XOR","summary":"Exclusive OR: one if the two inputs differ.","url":"glossary.html#xor"},{"kind":"Glossary","title":"XNOR","summary":"Exclusive NOR: one if the two inputs match.","url":"glossary.html#xnor"},{"kind":"Glossary","title":"NAND","summary":"The inverse of AND. A universal gate for constructing Boolean functions.","url":"glossary.html#nand"},{"kind":"Glossary","title":"NOR","summary":"The inverse of OR. A universal gate for constructing Boolean functions.","url":"glossary.html#nor"},{"kind":"Glossary","title":"Multiplexer","summary":"A selector that forwards one of several data inputs based on control inputs.","url":"glossary.html#multiplexer"},{"kind":"Glossary","title":"Demultiplexer","summary":"A routing block that sends one input toward a selected output.","url":"glossary.html#demultiplexer"},{"kind":"Glossary","title":"Decoder","summary":"A circuit translating a binary code into a selection or set of outputs.","url":"glossary.html#decoder"},{"kind":"Glossary","title":"Encoder","summary":"A circuit translating active input conditions into an encoded output; behavior depends on its specification.","url":"glossary.html#encoder"},{"kind":"Glossary","title":"Radix","summary":"The number base, such as two for binary or ten for decimal.","url":"glossary.html#radix"},{"kind":"Glossary","title":"Binary","summary":"A base-two positional number representation using 0 and 1.","url":"glossary.html#binary"},{"kind":"Glossary","title":"Decimal","summary":"A base-ten positional number representation using the digits 0 through 9.","url":"glossary.html#decimal"},{"kind":"Glossary","title":"Hexadecimal","summary":"Base sixteen: 0–9 and A–F, with one symbol per four bits.","url":"glossary.html#hexadecimal"},{"kind":"Glossary","title":"Nibble","summary":"Four bits; exactly one hexadecimal digit.","url":"glossary.html#nibble"},{"kind":"Glossary","title":"Most significant bit","summary":"The highest positional-weight bit in the chosen width.","url":"glossary.html#most-significant-bit"},{"kind":"Glossary","title":"Least significant bit","summary":"The lowest positional-weight bit, weight 1 for unsigned integers.","url":"glossary.html#least-significant-bit"},{"kind":"Glossary","title":"Unsigned integer","summary":"An interpretation where all bit-position weights are nonnegative.","url":"glossary.html#unsigned-integer"},{"kind":"Glossary","title":"Signed integer","summary":"An interpretation permitting negative values, commonly using two’s complement.","url":"glossary.html#signed-integer"},{"kind":"Glossary","title":"Two’s complement","summary":"A signed fixed-width representation that uses modular arithmetic and a negative leading-bit weight.","url":"glossary.html#two-s-complement"},{"kind":"Glossary","title":"Negation","summary":"Computing the additive inverse of a number; for two’s complement, invert bits and add one modulo 2ⁿ.","url":"glossary.html#negation"},{"kind":"Glossary","title":"Carry","summary":"A contribution passed to a more significant binary column in addition.","url":"glossary.html#carry"},{"kind":"Glossary","title":"Borrow","summary":"The corresponding concept in direct subtraction; many ALUs report no-borrow instead.","url":"glossary.html#borrow"},{"kind":"Glossary","title":"Overflow","summary":"A condition where a mathematical result falls outside the supported range of a representation.","url":"glossary.html#overflow"},{"kind":"Glossary","title":"Signed overflow","summary":"A result outside the fixed-width signed range; distinct from unsigned carry-out.","url":"glossary.html#signed-overflow"},{"kind":"Glossary","title":"Modulo","summary":"The remainder after division; n-bit arithmetic effectively wraps modulo 2ⁿ.","url":"glossary.html#modulo"},{"kind":"Glossary","title":"Bitwise operation","summary":"An operation that applies a logic rule independently to corresponding bits.","url":"glossary.html#bitwise-operation"},{"kind":"Glossary","title":"Half adder","summary":"A circuit adding two input bits with a sum and carry output.","url":"glossary.html#half-adder"},{"kind":"Glossary","title":"Full adder","summary":"A circuit adding A, B and carry-in, producing sum and carry-out.","url":"glossary.html#full-adder"},{"kind":"Glossary","title":"Ripple carry","summary":"An adder structure where carry must propagate between sequential bit stages.","url":"glossary.html#ripple-carry"},{"kind":"Glossary","title":"ALU","summary":"Arithmetic logic unit; circuitry selecting between arithmetic and bitwise operations.","url":"glossary.html#alu"},{"kind":"Glossary","title":"Datapath","summary":"The CPU components and connections that carry and transform data values.","url":"glossary.html#datapath"},{"kind":"Glossary","title":"Control unit","summary":"Logic coordinating instruction execution by driving selectors and enable signals.","url":"glossary.html#control-unit"},{"kind":"Glossary","title":"Combinational logic","summary":"Logic whose output is a function of current inputs alone, apart from propagation delay.","url":"glossary.html#combinational-logic"},{"kind":"Glossary","title":"Sequential logic","summary":"Logic whose behavior depends on inputs and retained state.","url":"glossary.html#sequential-logic"},{"kind":"Glossary","title":"Feedback","summary":"A connection where an output influences the same system again.","url":"glossary.html#feedback"},{"kind":"Glossary","title":"Latch","summary":"A state-holding element typically controlled by an enable level.","url":"glossary.html#latch"},{"kind":"Glossary","title":"Flip-flop","summary":"A state-holding element, typically triggered by a clock edge.","url":"glossary.html#flip-flop"},{"kind":"Glossary","title":"Setup time","summary":"Time an input must be stable before the sampling clock edge.","url":"glossary.html#setup-time"},{"kind":"Glossary","title":"Hold time","summary":"Time an input must remain stable after the sampling clock edge.","url":"glossary.html#hold-time"},{"kind":"Glossary","title":"Propagation delay","summary":"The finite time between an input change and the resulting output change.","url":"glossary.html#propagation-delay"},{"kind":"Glossary","title":"Clock","summary":"A periodic timing signal used to coordinate state changes in synchronous logic.","url":"glossary.html#clock"},{"kind":"Glossary","title":"Clock edge","summary":"A signal transition, commonly rising or falling, used as a sampling event.","url":"glossary.html#clock-edge"},{"kind":"Glossary","title":"Register","summary":"A small group of state elements holding a multi-bit value.","url":"glossary.html#register"},{"kind":"Glossary","title":"Register file","summary":"A collection of processor registers accessed through selection logic.","url":"glossary.html#register-file"},{"kind":"Glossary","title":"Counter","summary":"A sequential circuit whose stored number changes by a defined step.","url":"glossary.html#counter"},{"kind":"Glossary","title":"Accumulator","summary":"A register that frequently holds an ALU input and output in a simple CPU.","url":"glossary.html#accumulator"},{"kind":"Glossary","title":"Memory address","summary":"A code identifying a storage location or mapped peripheral location.","url":"glossary.html#memory-address"},{"kind":"Glossary","title":"Address bus","summary":"Signal lines carrying the address of a selected memory or device location.","url":"glossary.html#address-bus"},{"kind":"Glossary","title":"Data bus","summary":"Signal lines transporting data values between components.","url":"glossary.html#data-bus"},{"kind":"Glossary","title":"Control bus","summary":"The collection of control signals governing transfers or transactions.","url":"glossary.html#control-bus"},{"kind":"Glossary","title":"RAM","summary":"Random-access memory: locations that can be individually accessed for reading and usually writing.","url":"glossary.html#ram"},{"kind":"Glossary","title":"ROM","summary":"Read-only memory: a memory-like interface delivering pre-established data or lookup values.","url":"glossary.html#rom"},{"kind":"Glossary","title":"SRAM","summary":"Static random-access memory built from bistable storage cells; common in caches.","url":"glossary.html#sram"},{"kind":"Glossary","title":"DRAM","summary":"Dynamic random-access memory storing charge, requiring periodic refresh.","url":"glossary.html#dram"},{"kind":"Glossary","title":"Cache","summary":"Small, relatively fast storage for copies of likely-needed data or instructions.","url":"glossary.html#cache"},{"kind":"Glossary","title":"Instruction","summary":"An encoded command whose meaning is specified by an instruction set architecture.","url":"glossary.html#instruction"},{"kind":"Glossary","title":"Opcode","summary":"The instruction field indicating which operation is requested.","url":"glossary.html#opcode"},{"kind":"Glossary","title":"Operand","summary":"A value, register, address or encoded field used by an instruction.","url":"glossary.html#operand"},{"kind":"Glossary","title":"Immediate","summary":"A value carried directly inside an instruction encoding.","url":"glossary.html#immediate"},{"kind":"Glossary","title":"Instruction register","summary":"A register or pipeline state holding the instruction under interpretation.","url":"glossary.html#instruction-register"},{"kind":"Glossary","title":"Program counter","summary":"State identifying the address of the next instruction fetch under the architecture’s rules.","url":"glossary.html#program-counter"},{"kind":"Glossary","title":"PC","summary":"Abbreviation for program counter, not personal computer in this context.","url":"glossary.html#pc"},{"kind":"Glossary","title":"ISA","summary":"Instruction set architecture: the programmer-visible contract of instructions, registers and behavior.","url":"glossary.html#isa"},{"kind":"Glossary","title":"Microarchitecture","summary":"The internal circuit organization implementing an ISA.","url":"glossary.html#microarchitecture"},{"kind":"Glossary","title":"Microcode","summary":"Control information describing lower-level steps for implementing machine instructions.","url":"glossary.html#microcode"},{"kind":"Glossary","title":"Control ROM","summary":"A lookup table mapping control state and instruction fields to control outputs.","url":"glossary.html#control-rom"},{"kind":"Glossary","title":"Fetch","summary":"Obtaining instruction bits from instruction storage or memory.","url":"glossary.html#fetch"},{"kind":"Glossary","title":"Decode","summary":"Interpreting instruction fields to choose an operation and its operands.","url":"glossary.html#decode"},{"kind":"Glossary","title":"Execute","summary":"Performing the operation or state transition required by an instruction.","url":"glossary.html#execute"},{"kind":"Glossary","title":"Writeback","summary":"A stage that commits a computed result to an architectural destination in many CPU descriptions.","url":"glossary.html#writeback"},{"kind":"Glossary","title":"Branch","summary":"An instruction that conditionally or unconditionally selects a new control-flow target.","url":"glossary.html#branch"},{"kind":"Glossary","title":"Jump","summary":"An explicit change of the next instruction address.","url":"glossary.html#jump"},{"kind":"Glossary","title":"Flag","summary":"A status bit describing an operation’s outcome, such as zero or carry.","url":"glossary.html#flag"},{"kind":"Glossary","title":"Zero flag","summary":"A status bit indicating that the relevant operation produced zero.","url":"glossary.html#zero-flag"},{"kind":"Glossary","title":"Negative flag","summary":"A status bit often reflecting the result’s most significant bit.","url":"glossary.html#negative-flag"},{"kind":"Glossary","title":"Carry flag","summary":"A status bit associated with carry-out or no-borrow, depending on instruction semantics.","url":"glossary.html#carry-flag"},{"kind":"Glossary","title":"Conditional execution","summary":"The use of a condition to decide whether an operation or branch takes effect.","url":"glossary.html#conditional-execution"},{"kind":"Glossary","title":"Assembler","summary":"A program converting assembly mnemonics and operands to encoded machine instructions.","url":"glossary.html#assembler"},{"kind":"Glossary","title":"Assembly","summary":"A readable language closely related to an ISA’s machine instructions.","url":"glossary.html#assembly"},{"kind":"Glossary","title":"Machine code","summary":"Instruction encodings that can be recognized by a processor.","url":"glossary.html#machine-code"},{"kind":"Glossary","title":"Compiler","summary":"Software translating a higher-level program into another representation, often machine code.","url":"glossary.html#compiler"},{"kind":"Glossary","title":"Endianness","summary":"The order in which bytes of a multi-byte value are arranged in addressed memory.","url":"glossary.html#endianness"},{"kind":"Glossary","title":"ARM","summary":"A family of instruction set architectures and CPU designs widely used in many devices.","url":"glossary.html#arm"},{"kind":"Glossary","title":"ARMv6","summary":"A version of the ARM architecture supported by the ARM1176JZF-S family.","url":"glossary.html#armv6"},{"kind":"Glossary","title":"Load/store architecture","summary":"An architecture style in which memory access uses dedicated load/store instructions.","url":"glossary.html#load-store-architecture"},{"kind":"Glossary","title":"GPIO","summary":"General-purpose input/output pins used to exchange digital signals with external hardware.","url":"glossary.html#gpio"},{"kind":"Glossary","title":"MMIO","summary":"Memory-mapped input/output: device control registers accessed through an address space.","url":"glossary.html#mmio"},{"kind":"Glossary","title":"Peripheral","summary":"A component outside the processor’s arithmetic core, such as a GPIO controller or timer.","url":"glossary.html#peripheral"},{"kind":"Glossary","title":"SoC","summary":"System on a chip: a chip integrating CPU cores and additional controllers or accelerators.","url":"glossary.html#soc"},{"kind":"Glossary","title":"Interrupt","summary":"A mechanism redirecting execution to handle a hardware or software event.","url":"glossary.html#interrupt"},{"kind":"Glossary","title":"Exception","summary":"A special control-flow event such as a fault or deliberate system call.","url":"glossary.html#exception"},{"kind":"Glossary","title":"OS","summary":"Operating system: software coordinating hardware, programs, resources and protections.","url":"glossary.html#os"},{"kind":"Glossary","title":"Process","summary":"An operating-system abstraction for a running program and its execution resources.","url":"glossary.html#process"},{"kind":"Glossary","title":"Thread","summary":"An execution sequence sharing a process’s resources with peer threads.","url":"glossary.html#thread"},{"kind":"Glossary","title":"Scheduler","summary":"The operating-system component deciding when runnable tasks receive CPU time.","url":"glossary.html#scheduler"},{"kind":"Glossary","title":"Context switch","summary":"Saving one execution context and restoring another.","url":"glossary.html#context-switch"},{"kind":"Glossary","title":"Virtual memory","summary":"An address-space abstraction mapped to physical storage under system rules.","url":"glossary.html#virtual-memory"},{"kind":"Glossary","title":"Cache hit","summary":"A requested item is already present in the relevant cache.","url":"glossary.html#cache-hit"},{"kind":"Glossary","title":"Cache miss","summary":"A requested item is not present and must be obtained from another level.","url":"glossary.html#cache-miss"},{"kind":"Glossary","title":"Pipeline","summary":"A CPU structure overlapping stages of multiple in-flight instructions.","url":"glossary.html#pipeline"},{"kind":"Glossary","title":"Hazard","summary":"A dependency or resource conflict that can disturb overlapped execution.","url":"glossary.html#hazard"},{"kind":"Glossary","title":"Throughput","summary":"How much work a system completes per unit time.","url":"glossary.html#throughput"},{"kind":"Glossary","title":"Latency","summary":"How long an individual operation or request takes to complete.","url":"glossary.html#latency"},{"kind":"Glossary","title":"Concurrency","summary":"Multiple activities make progress during overlapping periods.","url":"glossary.html#concurrency"},{"kind":"Glossary","title":"Parallelism","summary":"Multiple activities execute simultaneously on distinct execution resources.","url":"glossary.html#parallelism"},{"kind":"Glossary","title":"Fibonacci sequence","summary":"A sequence where each term after the first two is the sum of the previous two.","url":"glossary.html#fibonacci-sequence"},{"kind":"Glossary","title":"Seven-segment display","summary":"An arrangement of seven individually controlled segments used to show digits.","url":"glossary.html#seven-segment-display"},{"kind":"Glossary","title":"Boolean expression","summary":"A formula built from true/false variables and logical operators.","url":"glossary.html#boolean-expression"},{"kind":"Glossary","title":"Fan-out","summary":"The number of receiving inputs driven by one output; affects circuit loading.","url":"glossary.html#fan-out"},{"kind":"Glossary","title":"Tri-state output","summary":"A digital output that may drive low, drive high, or electrically disconnect, depending on design.","url":"glossary.html#tri-state-output"},{"kind":"Glossary","title":"Bus contention","summary":"An electrical conflict when multiple active drivers attempt incompatible values on one shared connection.","url":"glossary.html#bus-contention"},{"kind":"Glossary","title":"Reset","summary":"A control operation initializing state to a defined condition.","url":"glossary.html#reset"},{"kind":"Glossary","title":"Enable","summary":"A signal allowing an operation, selection or state update when asserted.","url":"glossary.html#enable"},{"kind":"Glossary","title":"Decoder output","summary":"A selected line or combination of lines asserted according to an encoded input.","url":"glossary.html#decoder-output"},{"kind":"Glossary","title":"Combinational loop","summary":"Feedback without registered state; requires care because it may oscillate or behave unpredictably.","url":"glossary.html#combinational-loop"},{"kind":"Glossary","title":"Program trace","summary":"A step-by-step record of executed instructions and state changes.","url":"glossary.html#program-trace"},{"kind":"Glossary","title":"Microstep","summary":"A smaller internal control phase used to implement one architectural instruction.","url":"glossary.html#microstep"},{"kind":"Glossary","title":"Word","summary":"A group of bits of implementation- or architecture-defined size.","url":"glossary.html#word"},{"kind":"Glossary","title":"Register width","summary":"The number of bits held or processed by a particular register.","url":"glossary.html#register-width"},{"kind":"Glossary","title":"Instruction width","summary":"The number of bits in an encoded instruction; may be fixed or variable depending on ISA.","url":"glossary.html#instruction-width"},{"kind":"Glossary","title":"Address space","summary":"The range and meaning of addresses accessible to a processor or program.","url":"glossary.html#address-space"},{"kind":"Glossary","title":"Sampling","summary":"Capturing the value of a signal at a defined observation time.","url":"glossary.html#sampling"},{"kind":"Glossary","title":"Clock domain","summary":"A set of sequential components driven by a related clock signal.","url":"glossary.html#clock-domain"},{"kind":"Glossary","title":"Metastability","summary":"A temporary unresolved state possible when sampling asynchronous or badly timed signals.","url":"glossary.html#metastability"}];